--- XAVIER_INSERTS: CARGA COMPLETA DE MARCAS, MODELOS Y ANIOS
--- Contenido: 23 marcas, 301 modelos y 3411 combinaciones modelo-anio.
--- Ejecutar una sola vez, con FIDE_MARCAS_TB, FIDE_MODELOS_TB y FIDE_ANIOS_TB vacias.
--- El siguiente valor de ID_MARCA_SEQ, ID_MODELO_SEQ e ID_ANIO_SEQ debe ser 1.
--- Requiere ID_ESTADO = 1 existente y los triggers de insercion activos.
--- Cargar el archivo completo, en orden, sin otras inserciones simultaneas en estas tablas.
--- Incluye las 7 marcas, 12 modelos y 12 anios iniciales, con su numeracion original.
--- Esta carga sustituye las secciones de MARCAS, MODELOS y ANIOS del archivo inicial.
--- Cada INSERT usa solo valores literales. Confirmar con COMMIT despues de revisar.
--- Cada sentencia termina con punto y coma; la barra / volveria a ejecutar el INSERT.
--- Catalogo depurado de asociaciones incorrectas, etiquetas ambiguas y algunos anios imposibles.
--- Los rangos heredados restantes no se han verificado anio por anio; no acreditan cobertura del 99%.

--- FUENTES DE LAS CORRECCIONES HISTORICAS
--- Camaro: https://www.chevrolet.com/legacy/camaro
--- Bronco: https://media.ford.com/content/dam/fordmedia/img/MiddleEast/2024/August/The%20Bronco%20Through%20the%20Years%2059%20Years%20of%20Off-Road%20Excellence%20-%20ENG.pdf
--- Jeep CJ-5 y CJ-7: https://www.jeep.com/history/1970s.html
--- Jeep CJ-3: https://www.jeep.com/history/1940s.html
--- Jeep CJ-8: https://www.jeep.com/vn/en/history/1980s.html
--- Corvette: https://www.corvettemuseum.org/the-one-and-only-1983-corvette-a-new-chapter-in-corvette-history-at-the-national-corvette-museum/

